:"authenticator","table":"public.events","allowed":false,"privilege":"REFERENCES"},{"role":"authenticator","table":"public.events","allowed":false,"privilege":"SELECT"},{"role":"authenticator","table":"public.events","allowed":false,"privilege":"TRIGGER"},{"role":"authenticator","table":"public.events","allowed":false,"privilege":"TRUNCATE"},{"role":"authenticator","table":"public.events","allowed":false,"privilege":"UPDATE"},{"role":"authenticator","table":"public.profiles","allowed":false,"privilege":"DELETE"},{"role":"authenticator","table":"public.profiles","allowed":false,"privilege":"INSERT"},{"role":"authenticator","table":"public.profiles","allowed":false,"privilege":"REFERENCES"},{"role":"authenticator","table":"public.profiles","allowed":false,"privilege":"SELECT"},{"role":"authenticator","table":"public.profiles","allowed":false,"privilege":"TRIGGER"},{"role":"authenticator","table":"public.profiles","allowed":false,"privilege":"TRUNCATE"},{"role":"authenticator","table":"public.profiles","allowed":false,"privilege":"UPDATE"},{"role":"authenticator","table":"public.registrations","allowed":false,"privilege":"DELETE"},{"role":"authenticator","table":"public.registrations","allowed":false,"privilege":"INSERT"},{"role":"authenticator","table":"public.registrations","allowed":false,"privilege":"REFERENCES"},{"role":"authenticator","table":"public.registrations","allowed":false,"privilege":"SELECT"},{"role":"authenticator","table":"public.registrations","allowed":false,"privilege":"TRIGGER"},{"role":"authenticator","table":"public.registrations","allowed":false,"privilege":"TRUNCATE"},{"role":"authenticator","table":"public.registrations","allowed":false,"privilege":"UPDATE"}]}$evidence$::jsonb AS j),
checks AS (
 SELECT 'PARITY constraint' AS category,e->>'name' AS item,
  coalesce(c.contype::text=e->>'kind' AND c.convalidated=(e->>'validated')::boolean
   AND c.condeferrable=(e->>'deferrable')::boolean AND c.condeferred=(e->>'initially_deferred')::boolean
   AND pg_get_constraintdef(c.oid,true)=e->>'definition',false) AS ok,
  coalesce(pg_get_constraintdef(c.oid,true),'MISSING') AS actual
 FROM expected CROSS JOIN LATERAL jsonb_array_elements(j->'constraints') e
 LEFT JOIN pg_constraint c ON c.conrelid=to_regclass('public.'||(e->>'table')) AND c.conname=e->>'name'
 UNION ALL
 SELECT 'PARITY index',e->>'index',
  coalesce(i.indisunique AND i.indisvalid AND i.indisready
   AND pg_get_indexdef(i.indexrelid)=e->>'definition',false),
  coalesce(pg_get_indexdef(i.indexrelid),'MISSING')
 FROM expected CROSS JOIN LATERAL jsonb_array_elements(j->'indexes') e
 LEFT JOIN pg_index i ON i.indexrelid=to_regclass('public.'||(e->>'index'))
  AND i.indrelid=to_regclass('public.'||(e->>'table'))
 UNION ALL
 SELECT 'PARITY trigger',e->>'name',
  coalesce(NOT t.tgisinternal AND t.tgenabled::text=e->>'enabled'
   AND t.tgfoid=to_regprocedure('public.'||(e->>'function'))
   AND pg_get_triggerdef(t.oid,true)=e->>'definition',false),
  coalesce(pg_get_triggerdef(t.oid,true),'MISSING')
 FROM expected CROSS JOIN LATERAL jsonb_array_elements(j->'triggers') e
 LEFT JOIN pg_trigger t ON t.tgrelid=to_regclass(CASE WHEN e->>'table' LIKE '%.%' THEN e->>'table' ELSE 'public.'||(e->>'table') END)
  AND t.tgname=e->>'name'
 UNION ALL
 SELECT 'PARITY function',e->>'signature',
  coalesce(p.prosecdef=(e->>'security_definer')::boolean
   AND pg_get_userbyid(p.proowner)=e->>'owner' AND l.lanname=e->>'language'
   AND pg_get_function_result(p.oid)=e->>'result'   
   AND to_jsonb(p.proconfig)=(e->'settings')
   AND to_jsonb(p.proacl::text[]) @> (e->'acl')
   AND to_jsonb(p.proacl::text[]) <@ (e->'acl'),false),
  CASE WHEN p.oid IS NULL THEN 'MISSING' ELSE jsonb_build_object(
    'owner',pg_get_userbyid(p.proowner),'definer',p.prosecdef,'language',l.lanname,
    'result',pg_get_function_result(p.oid),'settings',p.proconfig,'acl',p.proacl)::text END
 FROM expected CROSS JOIN LATERAL jsonb_array_elements(j->'functions') e
 LEFT JOIN pg_proc p ON p.oid=to_regprocedure('public.'||(e->>'signature'))
 LEFT JOIN pg_language l ON l.oid=p.prolang
 UNION ALL
 SELECT 'PARITY privilege',(e->>'role')||' / '||(e->>'table')||' / '||(e->>'privilege'),
  coalesce(has_table_privilege(r.oid,c.oid,e->>'privilege')=(e->>'allowed')::boolean,false),
  'expected='||(e->>'allowed')||', actual='||coalesce(has_table_privilege(r.oid,c.oid,e->>'privilege')::text,'MISSING')
 FROM expected CROSS JOIN LATERAL jsonb_array_elements(j->'privileges') e
 LEFT JOIN pg_roles r ON r.rolname=e->>'role'
 LEFT JOIN pg_class c ON c.oid=to_regclass(e->>'table')
 UNION ALL
 SELECT 'PARITY inventory','constraints',count(*)=19,count(*)::text||' / expected 19'
 FROM pg_constraint WHERE conrelid IN (to_regclass('public.profiles'),to_regclass('public.events'),to_regclass('public.registrations'),to_regclass('public.attendance'))
 UNION ALL
 SELECT 'PARITY inventory','indexes',count(*)=7,count(*)::text||' / expected 7'
 FROM pg_index WHERE indrelid IN (to_regclass('public.profiles'),to_regclass('public.events'),to_regclass('public.registrations'),to_regclass('public.attendance'))
 UNION ALL
 SELECT 'PARITY inventory','application triggers',count(*)=2,count(*)::text||' / expected 2'
 FROM pg_trigger WHERE NOT tgisinternal AND
 (tgrelid IN (to_regclass('public.profiles'),to_regclass('public.events'),to_regclass('public.registrations'),to_regclass('public.attendance'))
 OR (tgrelid=to_regclass('auth.users') AND tgname='on_auth_user_created'))
 UNION ALL
 SELECT 'PARITY inventory','function overloads',count(*)=6,count(*)::text||' / expected 6'
 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
 WHERE n.nspname='public' AND p.proname IN ('handle_new_user','validate_event_capacity','check_in_ticket','get_attendance_records','get_event_registration_counts','register_for_event')
 UNION ALL
 SELECT 'SECURITY','legacy TRUNCATE: '||r.rolname||' / '||c.relname,
  NOT has_table_privilege(r.oid,c.oid,'TRUNCATE'),
  CASE WHEN has_table_privilege(r.oid,c.oid,'TRUNCATE') THEN 'EXCESS PRIVILEGE PRESENT; expected legacy risk, not security approval' ELSE 'TRUNCATE absent' END
 FROM pg_roles r CROSS JOIN pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE r.rolname IN ('anon','authenticated') AND n.nspname='public'
  AND c.relname IN ('profiles','events','registrations','attendance')
)
SELECT category,item,CASE WHEN ok THEN 'PASS' ELSE 'FAIL' END AS result,actual
FROM checks
UNION ALL
SELECT 'PARITY SUMMARY','remaining metadata checks',
 CASE WHEN bool_and(ok) THEN 'PASS' ELSE 'FAIL' END,
 count(*) FILTER(WHERE NOT ok)::text||' parity failures; excludes SECURITY rows and live authorization tests'
FROM checks WHERE category LIKE 'PARITY%'
ORDER BY category,item;
ROLLBACK;
